 @Override public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;String previous=getTargetContext().getSharedPreferences("secure",0).getString("settings",null);try{h=new MainHost(this);h.open();if(phase.equals("seed"))seedChat();else if(phase.equals("narrow"))narrowChat();else if(phase.equals("live"))liveChat();else if(phase.equals("audit"))auditChat();else verifyChat();result.putString("stream","PASS "+passed+" chat/session/memory/UI checks; phase="+phase+"\n");code=Activity.RESULT_OK;}catch(Throwable ex){String diagnostic="";if(phase.equals("live")&&h!=null)try{diagnostic=" Last synthetic reply: "+h.js("Array.from(document.querySelectorAll('.chat-message')).slice(-1).map(e=>e.innerText).join('').slice(0,1500)");}catch(Exception ignored){}result.putString("stream","FAIL after "+passed+": "+ex.getClass().getSimpleName()+" / "+ex.getMessage()+diagnostic+"\n");}finally{if(phase.equals("live")){android.content.SharedPreferences.Editor ed=getTargetContext().getSharedPreferences("secure",0).edit();if(previous==null)ed.remove("settings");else ed.putString("settings",previous);ed.commit();liveKey="";}}finish(code,result);
 }
